<# Pure/mocked tests only. No VM, physical-device or virtual-disk API calls. #>
[CmdletBinding()]param()
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$script:checks=0
function Check([bool]$Value,[string]$Message){if(-not$Value){throw $Message};$script:checks++}
function Reject([scriptblock]$Action,[string]$Message){$failed=$false;try{& $Action|Out-Null}catch{$failed=$true};Check $failed $Message}
function Clone($Value){$copy=$Value|ConvertTo-Json -Depth 40|ConvertFrom-Json;if($copy-is[array]){foreach($item in $copy){$item}}else{$copy}}
$wrapper=Join-Path $PSScriptRoot 'guest\Invoke-GuestShadowReadOnlyAttachment.ps1';$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($wrapper,[ref]$tokens,[ref]$errors);Check ($errors.Count-eq0) 'Wrapper parse failed.'
foreach($f in $ast.FindAll({param($n)$n-is[Management.Automation.Language.FunctionDefinitionAst]},$false)){Invoke-Expression $f.Extent.Text}
$native=Join-Path $PSScriptRoot 'guest\NativeShadowReadOnlyAttachment.cs';Add-Type -Path @((Join-Path $PSScriptRoot 'guest\NativeShadowDisk.cs'),(Join-Path $PSScriptRoot 'guest\NativeMountBoundary.cs'),$native,(Join-Path $PSScriptRoot 'NativeMountBoundary.TestSupport.cs'),(Join-Path $PSScriptRoot 'NativeShadowReadOnlyAttachment.TestSupport.cs'))
function Observe($Fake,[bool]$Establish=$true){[Ntfs2Refs.NativeShadowProtection]::ObserveWith($Fake,$Fake.Disk,$Fake.Partition,$Establish)}
$p=[Ntfs2Refs.ReadOnlyShadowDiskApi]::OpenParameters();Check ($p.Version-eq2-and$p.GetInfoOnly-eq0-and$p.ReadOnly-eq1-and$p.ResiliencyGuid-eq[guid]::Empty) 'Read-only V2 open layout differs.'
Check ([Ntfs2Refs.ReadOnlyShadowDiskApi]::AttachFlags-eq7) 'Attach must combine only read-only/no-letter/permanent-lifetime.'
$api=New-Object Ntfs2Refs.ReadOnlyShadowDiskApi;$unused=[IntPtr]::Zero;Reject {$api.Create('unused',[guid]::NewGuid(),[ref]$unused)} 'Creation must be unavailable.'
$b=[Ntfs2Refs.NativeShadowProtection]::ExclusionInput();Check ($b.Length-eq40-and[BitConverter]::ToUInt32($b,0)-eq40-and$b[4]-eq1-and[BitConverter]::ToUInt64($b,8)-eq3-and[BitConverter]::ToUInt64($b,16)-eq3) 'Explicit persistent exclusion layout differs.';Check (@($b[5..7]+$b[24..39]|Where-Object{$_-ne0}).Count-eq0) 'Reserved SET bytes changed.'
foreach($attrs in 0..3){$f=New-Object ShadowProtectionFake;$f.Attributes=$attrs;$r=Observe $f $false;Check ($r.operationCompletionKnown-and$r.cleanupComplete-and$r.providerReadOnlyBefore-and$r.providerReadOnlyAfter-and$r.attributesBefore-eq$attrs-and$r.attributesAfter-eq$attrs) 'Observe-only control failed.';Check ($f.Sets-eq0-and$f.WriteOpens-eq0-and$f.Closes-eq1-and$r.exclusionObserved-eq($attrs-eq3)) 'Observe-only mutated or inferred exclusion.'}
foreach($attrs in 0..3){$f=New-Object ShadowProtectionFake;$f.Attributes=$attrs;$r=Observe $f;Check ($r.status-ceq'provider-readonly-and-offline-observed'-and$r.exclusionObserved-and$r.operationCompletionKnown-and$r.cleanupComplete-and$r.attributesAfter-eq3) 'Explicit exclusion failed.';Check ($f.Sets-eq$(if($attrs-eq3){0}else{1})-and$f.WriteOpens-eq$(if($attrs-eq3){0}else{1})) 'Repeated/unnecessary attribute request.';Check (-not$r.rawPayloadWriteRequestsIssued-and-not$r.conversionQualified-and-not$r.persistenceQualified) 'Unsupported authority claimed.';if($attrs-ne3){Check ($f.Trace.IndexOf('query:'+([Ntfs2Refs.NativeMountBoundary]::WritableCode))-lt$f.Trace.IndexOf('open-write')-and$f.Trace.IndexOf('open-write')-lt$f.Trace.IndexOf('set')) 'Provider protection must precede attribute access/set.'}}
foreach($errorCode in @(0,5,21,87)){$f=New-Object ShadowProtectionFake;$f.WritableError=$errorCode;$r=Observe $f;Check ($r.status-ceq'blocked'-and-not$r.providerReadOnlyBefore-and$f.WriteOpens-eq0-and$f.Sets-eq0-and$r.cleanupComplete) 'Only ERROR_WRITE_PROTECT qualifies before attribute access.'}
foreach($field in @('WrongDevice','WrongLength','WrongAlignment','WrongLayout','Malformed')){$f=New-Object ShadowProtectionFake;$f.$field=$true;$r=Observe $f;Check ($r.status-ceq'blocked'-and$f.Sets-eq0-and$f.WriteOpens-eq0-and$r.operationCompletionKnown-and$r.cleanupComplete) ('Bad native binding accepted: '+$field)}
$f=New-Object ShadowProtectionFake;$f.Attributes=4;$r=Observe $f;Check ($r.status-ceq'blocked'-and$f.Sets-eq0) 'Unknown disk attribute bits accepted.'
$f=New-Object ShadowProtectionFake;$f.WrongPreSetLayout=$true;$r=Observe $f;Check ($r.status-ceq'blocked'-and$f.WriteOpens-eq1-and$f.Sets-eq0-and$r.cleanupComplete) 'Changed identity on attribute handle accepted.'
$f=New-Object ShadowProtectionFake;$f.WriteOpenError=5;$r=Observe $f;Check ($r.status-ceq'provider-readonly-attribute-access-refused'-and$r.attributeOpenReturned-and-not$r.attributeSetAttempted-and$r.providerReadOnlyAfter-and$r.cleanupComplete) 'Known access refusal lost measured protected state.'
$f=New-Object ShadowProtectionFake;$f.SetError=19;$r=Observe $f;Check ($r.status-ceq'provider-readonly-attribute-request-refused'-and$r.attributeSetReturned-and-not$r.attributeSetSucceeded-and$r.attributesAfter-eq0-and$r.cleanupComplete) 'Known SET refusal normalized/lost.'
$f=New-Object ShadowProtectionFake;$f.IgnoreSet=$true;$r=Observe $f;Check ($r.status-ceq'blocked'-and$r.attributeSetSucceeded-and-not$r.exclusionObserved-and$r.cleanupComplete) 'Success code without observed exclusion accepted.'
$f=New-Object ShadowProtectionFake;$f.ChangeUnrequested=$true;$r=Observe $f $false;Check ($r.status-ceq'blocked'-and$f.Sets-eq0) 'Unrequested attribute change accepted.'
foreach($q in @(1,4,6,7,12,14,19)){$f=New-Object ShadowProtectionFake;$f.ThrowQuery=$q;$r=Observe $f;Check (-not$r.operationCompletionKnown-and-not$r.cleanupComplete-and$f.Closes-eq0) ('Unknown query cleaned up: '+$q)}
foreach($q in @(1,4,6,7,12,14,19)){$f=New-Object ShadowProtectionFake;$f.FailQuery=$q;$r=Observe $f;Check ($r.operationCompletionKnown-and$r.cleanupComplete-and$r.status-ceq'blocked') ('Known query refusal lost completion: '+$q)}
$f=New-Object ShadowProtectionFake;$f.ThrowOpen=$true;$r=Observe $f;Check (-not$r.operationCompletionKnown-and$f.Closes-eq0-and$f.Sets-eq0) 'Unknown open cleanup attempted.'
$f=New-Object ShadowProtectionFake;$f.ThrowSet=$true;$r=Observe $f;Check (-not$r.operationCompletionKnown-and$r.attributeSetAttempted-and-not$r.attributeSetReturned-and$f.Closes-eq0) 'Unknown SET completion/handles not preserved.'
foreach($unknown in @($false,$true)){$f=New-Object ShadowProtectionFake;if($unknown){$f.ThrowClose=$true}else{$f.CloseError=6};$r=Observe $f;Check ($r.status-ceq'cleanup-failed'-and-not$r.cleanupComplete-and$r.operationCompletionKnown-eq(-not$unknown)-and$f.Closes-eq1) 'Cleanup failure retried or hidden.'}
$f=New-Object ShadowProtectionFake;$f.AliasHandles=$true;$r=Observe $f;Check (-not$r.cleanupComplete-and$f.Closes-eq1) 'Aliased handles closed twice.'
$f=New-Object ShadowProtectionFake;Reject {[Ntfs2Refs.NativeShadowProtection]::ObserveWith($f,[guid]::Empty,$f.Partition,$true)} 'Empty GPT accepted.';Reject {[Ntfs2Refs.NativeShadowProtection]::ObserveWith($f,$f.Disk,$f.Disk,$true)} 'Aliased GPT accepted.';Check ($f.Opens-eq0) 'Invalid identity invoked native fake.'
foreach($c in $r.calls){Check ($c.capacity-le65536-and$c.returned-le$c.capacity-and($null-eq$c.outputHex-or$c.outputHex.Length-le131072)) 'Response bound changed.'}

# Real archived proof bytes, parsed only; no guest top-level script execution.
$case=Join-Path (Split-Path $PSScriptRoot -Parent) '.lab\hyperv\retained-native-probe\win11-20261024T035910091Z';$prepPath=Join-Path $case 'shadow-platform.json';$probePath=Join-Path $case 'first-native\probe.json'
Check ((Get-FileHash $prepPath).Hash.ToLowerInvariant()-ceq'fd582940e925891350e308f97740f9f04c350b288537773b297724985518abe9') 'Preparation pin differs.';Check ((Get-FileHash $probePath).Hash.ToLowerInvariant()-ceq'89ff56d8a5695019c992a50b8ae73515e155fb0002c763952d1fa2be19d54a5b') 'Isolated probe pin differs.'
Import-SRAGuards (Get-Content (Join-Path $PSScriptRoot 'guest\Restore-GuestShadowAttachment.ps1') -Raw) @('Assert-AttachmentBoolean','Assert-AttachmentGuid','Assert-AttachmentPreparation','Assert-AttachmentOriginalDisks')
Import-SRAGuards (Get-Content (Join-Path $PSScriptRoot 'guest\Invoke-GuestNativeProbe.ps1') -Raw) @('Assert-NativeProbeFields','Assert-NativeProbeGuid','Assert-NativeProbeBinding','Assert-NativeProbeRequest','Assert-NativeProbeSame','Assert-NativeProbeResult')
$prep=Get-Content $prepPath -Raw|ConvertFrom-Json;$probe=Get-Content $probePath -Raw|ConvertFrom-Json;Assert-SRABindings $prep $probe;$script:checks++
foreach($field in @('runId','status','backingPath','nativeSourceSha256')){$bad=Clone $prep;$bad.$field='wrong';Reject {Assert-SRABindings $bad $probe} 'Changed preparation accepted.'}
$bad=Clone $prep;$bad.finalVhd.virtualDiskId=[guid]::NewGuid().ToString();Reject {Assert-SRABindings $bad $probe} 'Changed stable VHD identity accepted.'
$bad=Clone $probe;$bad.request.shadow.identity.disk_guid=[guid]::NewGuid().ToString();Reject {Assert-SRABindings $prep $bad} 'Changed shadow GPT accepted.'
$ids=@('60022480BEA35BA9D496D5AFF633D768','60022480D091C4251B5FFD619706C2B5','600224806AAC261F021F249596F332FC');$disks=@(for($i=0;$i-lt3;$i++){[pscustomobject]@{Number=$i;UniqueId=$ids[$i];Size=$(if($i-eq2){8GB}else{64GB});LogicalSectorSize=512;PhysicalSectorSize=4096;IsBoot=($i-eq0);IsSystem=($i-eq0);IsOffline=($i-eq1);IsReadOnly=$false;PartitionStyle='GPT';Guid=$(if($i-eq1){$probe.request.target.identity.disk_guid}elseif($i-eq2){$prep.journal.diskGuid}else{[guid]::NewGuid().ToString()})}})
Assert-SRAOriginal $disks $prep $probe;$script:checks++
foreach($i in 0..2){foreach($field in @('Number','UniqueId','Size','LogicalSectorSize','PhysicalSectorSize','IsBoot','IsSystem','IsOffline','IsReadOnly')){$bad=@(Clone $disks);$bad[$i].$field=if($bad[$i].$field-is[bool]){-not$bad[$i].$field}else{'wrong'};Reject {Assert-SRAOriginal $bad $prep $probe} ('Changed original inventory accepted: '+$i+'/'+$field)}}
$commands=@($ast.FindAll({param($n)$n-is[Management.Automation.Language.CommandAst]},$true)|ForEach-Object{$_.GetCommandName()});foreach($name in @('Set-Disk','Set-Partition','Format-Volume','Initialize-Disk','New-Partition','Mount-DiskImage','Dismount-DiskImage','Start-VM','Stop-VM','Restore-VMSnapshot')){Check ($name-cnotin$commands) ('Unexpected mutation command: '+$name)}
$code=Get-Content $native -Raw;Check ($code-notmatch 'extern.*(?:CreateVirtualDisk|DetachVirtualDisk|WriteFile|ReadFile|SetFilePointer)\(') 'Unexpected payload/create/detach API.'
$args=@{RunId='94f6256f57424ad69147f58199387ee1';ObservationId=('b'*32);DiagnosticNativeSourceSha256=('c'*64)};$result=& $wrapper @args -WhatIf;Check ($result.Status-ceq'what-if'-and-not$result.ConversionQualified) 'WhatIf reached guest preflight.'
foreach($field in @('RunId','ObservationId','DiagnosticNativeSourceSha256')){$bad=$args.Clone();$bad[$field]+="`n";Reject {& $wrapper @bad -WhatIf} 'Trailing newline accepted.'}
Write-Output ('PASS: '+$script:checks+' read-only shadow attachment checks; no VM/device calls.')
